*{box-sizing:border-box} :root{--ink:#f3f1e8;--muted:#a5b1a7;--faint:#718078;--line:rgba(222,232,218,.12);--panel:rgba(17,29,25,.82);--mint:#b6d79d;--gold:#e6bc76;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Space Grotesk',sans-serif}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#14211c;color:var(--ink);font-family:var(--sans);user-select:none}button{font:inherit;color:inherit}.game-shell{position:relative;width:100%;height:100%;min-height:520px;overflow:hidden;background:#253a2d}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 48%,transparent 25%,rgba(9,17,14,.2) 76%,rgba(8,15,12,.54) 130%);z-index:1}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:72px;padding:0 31px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(9,18,15,.74),rgba(9,18,15,0));}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#dfe6d9;font:500 10px var(--mono);letter-spacing:.15em}.brand b{color:#87968a;font-weight:400}.brand-mark{font-size:21px;color:#c1d69b}.day-pill{position:absolute;left:50%;transform:translateX(-50%);display:flex;gap:10px;align-items:center;background:rgba(14,26,21,.63);border:1px solid rgba(233,238,218,.14);border-radius:24px;padding:8px 14px;font:10px var(--mono);letter-spacing:.1em;color:#dce4d9;backdrop-filter:blur(12px)}.day-pill i{height:12px;width:1px;background:rgba(255,255,255,.25)}#weatherLabel{color:#bac5b8}.live-dot{height:6px;width:6px;background:#a6d68d;border-radius:100%;box-shadow:0 0 9px #a6d68d;display:inline-block}.icon-button{width:35px;height:35px;background:rgba(15,26,22,.58);border:1px solid var(--line);border-radius:50%;cursor:pointer;color:#d1d9cb;font-size:16px}.glass{background:linear-gradient(135deg,rgba(17,30,25,.88),rgba(15,26,23,.78));border:1px solid rgba(223,234,216,.13);box-shadow:0 14px 40px rgba(0,0,0,.2);backdrop-filter:blur(15px);border-radius:9px}.left-panel{position:absolute;z-index:2;left:30px;top:96px;width:244px;padding:17px 17px 14px}.section-heading,.map-head{display:flex;justify-content:space-between;align-items:center;color:#c4cfc3;font:9px var(--mono);letter-spacing:.13em}.status-chip{font-size:8px;padding:4px 7px;border-radius:3px;background:rgba(163,204,137,.12);color:#bdd8a7;letter-spacing:.08em}.vitals{display:grid;gap:14px;padding:18px 0 17px}.vital-row{display:flex;gap:10px;align-items:center}.vital-icon{width:26px;height:26px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.1);border-radius:6px;color:#e3ba77;font-size:15px}.vital-icon.thirst{color:#89c9c5}.vital-icon.health{color:#e5967b}.vital-info{flex:1}.vital-label{display:flex;justify-content:space-between;margin-bottom:6px;font:8px var(--mono);letter-spacing:.08em;color:#bac5ba}.vital-label span+span{color:#e0e8dc}.meter{height:3px;background:rgba(237,241,222,.12);border-radius:5px;overflow:hidden}.meter-fill{height:100%;display:block;border-radius:5px;transition:width .25s}.hunger-fill{background:#dbb36f}.thirst-fill{background:#7ec2bd}.health-fill{background:#d98172}.panel-divider{height:1px;background:var(--line);margin:0 -1px 14px}.tiny-count{color:#87978b;font-size:9px;letter-spacing:.04em}.log-copy{font-size:11px;line-height:1.55;color:#aab8aa;margin:12px 0 13px}.objective{border-top:1px solid var(--line);padding-top:12px;display:flex;align-items:center;gap:8px;color:#dce6d5;font-size:10px}.objective-icon{font-size:17px;color:#c8d79c}.right-panel{position:absolute;z-index:2;right:28px;top:96px;width:220px;display:grid;gap:10px}.map-card,.inventory-card,.quick-actions{padding:13px 13px 12px}.map-head{font-size:8px;letter-spacing:.11em}.map-coord{font-size:8px;letter-spacing:.02em;color:#8e9e91}#minimap{width:100%;height:auto;aspect-ratio:1;margin:11px 0 7px;border-radius:5px;background:#263f31;border:1px solid rgba(255,255,255,.07)}.map-legend{display:flex;gap:15px;font:8px var(--mono);color:#9eada0;letter-spacing:.08em}.map-legend span{display:flex;align-items:center;gap:5px}.map-legend i{width:6px;height:6px;border-radius:50%;display:inline-block}.legend-you{background:#f1dd9e}.legend-water{background:#70b9bc}.inventory-card{padding-bottom:13px}.inventory-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-top:11px}.inv-item{height:41px;border:1px solid rgba(230,239,222,.08);background:rgba(229,240,220,.035);border-radius:4px;position:relative;display:grid;place-items:center;color:#d9d5a5;font-size:17px}.inv-item em{position:absolute;bottom:2px;right:4px;font:8px var(--mono);font-style:normal;color:#e2e8d8}.inv-item.empty{color:rgba(222,232,218,.12)}.action-list{display:grid;margin-top:8px}.action-button{height:43px;display:flex;gap:9px;align-items:center;text-align:left;background:none;border:0;border-top:1px solid rgba(226,237,221,.07);padding:4px 1px;cursor:pointer}.action-button:hover{background:rgba(220,237,205,.06)}.action-icon{font-size:17px;color:#e2bd78;width:19px;text-align:center}.water-icon{color:#80c8c0}.fire-icon{color:#e69a69}.action-button>span:nth-child(2){flex:1}.action-button b{display:block;font-size:10px;font-weight:600;color:#e0e8da}.action-button small{display:block;margin-top:3px;font:8px var(--mono);color:#87978c}.action-button em{font:10px var(--mono);font-style:normal;color:#ccd8c8}.action-button kbd,.controls-note kbd{font:8px var(--mono);color:#aab7a8;background:rgba(232,239,223,.09);border:1px solid rgba(232,239,223,.1);padding:1px 4px;border-radius:2px}.shelter-tip{display:flex;gap:9px;padding:3px 4px;color:#c4ceba;align-items:center}.shelter-tip>span{font-size:19px;color:#d4be8b}.shelter-tip p{font-size:9px;line-height:1.45;color:#9eab9e;margin:0}.shelter-tip b{font-weight:600;color:#dce3d6}.bottom-ui{position:absolute;z-index:3;bottom:24px;left:0;right:0;display:flex;flex-direction:column;align-items:center;gap:10px;pointer-events:none}.hotbar{height:75px;display:flex;align-items:center;padding:7px;pointer-events:auto}.hot-slot{position:relative;width:67px;height:59px;border:1px solid transparent;border-radius:5px;background:transparent;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;cursor:pointer}.hot-slot.selected{background:rgba(188,213,158,.11);border-color:rgba(195,218,162,.3)}.slot-key{position:absolute;top:3px;left:5px;color:#829287;font:8px var(--mono)}.slot-symbol{font-size:19px;color:#dfc07d;line-height:22px}.hot-slot:nth-child(2) .slot-symbol{color:#88c9c5}.hot-slot:nth-child(3) .slot-symbol{color:#e8a06c}.build-slot .slot-symbol{color:#bacb9b}.slot-label{font:7px var(--mono);letter-spacing:.1em;color:#b8c5b7}.hotbar-sep{height:35px;width:1px;background:var(--line);margin:0 5px}.controls-note{margin-left:10px;color:#87968b;font:8px var(--mono);letter-spacing:.04em;white-space:nowrap}.controls-note kbd{margin:0 3px;color:#c4d0c0}.interaction-hint{min-height:27px;padding:5px 11px;background:rgba(13,23,19,.78);border:1px solid rgba(222,236,215,.15);border-radius:5px;display:flex;align-items:center;gap:8px;color:#dce6d7;font-size:10px;opacity:0;transition:opacity .2s;backdrop-filter:blur(9px)}.interaction-hint.visible{opacity:1}.keycap{font:9px var(--mono);padding:3px 6px;border:1px solid rgba(220,232,214,.28);border-radius:3px;color:#e7d9a8}.toast{position:absolute;z-index:6;left:50%;top:85px;transform:translate(-50%,-8px);padding:10px 16px;border:1px solid rgba(223,237,211,.17);background:rgba(15,27,22,.9);border-radius:5px;font:10px var(--mono);letter-spacing:.03em;color:#dfe9d9;opacity:0;transition:all .22s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.overlay{position:absolute;z-index:10;inset:0;background:rgba(8,15,12,.68);backdrop-filter:blur(6px);display:flex;justify-content:center;align-items:center}.overlay.hidden{display:none}.start-card{width:min(440px,calc(100vw - 36px));padding:33px 41px 27px;background:linear-gradient(145deg,rgba(25,41,33,.98),rgba(17,30,25,.98));border:1px solid rgba(223,236,216,.19);border-radius:10px;box-shadow:0 25px 100px rgba(0,0,0,.45);position:relative;text-align:center}.eyebrow{font:9px var(--mono);color:#a8b8a5;letter-spacing:.16em;display:flex;align-items:center;justify-content:center;gap:8px}.title-mark{font-size:28px;color:#c4d89e;margin:21px 0 6px}h1{font:700 56px/.84 var(--display);letter-spacing:.06em;margin:0;color:#e9eddf}h1 span{color:#c3d29c}.intro{font-size:13px;color:#b0beb0;margin:16px 0 22px}.start-rule{height:1px;background:linear-gradient(90deg,transparent,rgba(220,232,214,.2),transparent);margin:0 0 19px}.start-details{text-align:left;display:grid;gap:13px;margin-bottom:23px}.start-details div{display:grid;gap:5px}.start-details b{font:8px var(--mono);letter-spacing:.12em;color:#a9bd97}.start-details span{font-size:11px;color:#d0d9ce}.primary-button{height:43px;width:100%;border:0;border-radius:4px;background:#c4d49f;color:#17231b;font:700 10px var(--mono);letter-spacing:.11em;cursor:pointer;transition:background .15s,transform .15s}.primary-button:hover{background:#d2e2ad;transform:translateY(-1px)}.primary-button span{font-size:16px;margin-left:10px}.start-controls{font:8px var(--mono);letter-spacing:.055em;color:#819185;margin-top:17px}.start-controls i{font-style:normal;color:#55685b;margin:0 5px}.overlay-side-note{position:absolute;bottom:24px;font:8px var(--mono);letter-spacing:.15em;color:#96a393}.overlay-side-note span{color:#c0c99d}.end-card .title-mark{color:#df9d77}.end-card h1{font-size:42px}.end-card .start-details{margin-top:0}.end-card .eyebrow{display:block}.end-card .intro{line-height:1.6}.touch-controls{display:none}
@media(max-width:850px){.left-panel{left:16px;top:83px;width:210px;padding:13px}.right-panel{right:16px;top:83px;width:195px}.vitals{gap:10px;padding:13px 0}.map-card,.inventory-card,.quick-actions{padding:11px}.map-card #minimap{margin:8px 0 5px}.topbar{padding:0 17px}.bottom-ui{bottom:15px}.hotbar{height:68px}.hot-slot{width:57px;height:53px}.controls-note{font-size:7px}}
@media(max-width:620px){.game-shell{min-height:480px}.topbar{height:58px}.brand{font-size:8px}.brand-mark{font-size:18px}.day-pill{top:12px;font-size:8px;padding:7px 10px;gap:7px}.icon-button{width:30px;height:30px}.left-panel{top:69px;left:10px;width:calc(50% - 15px);padding:10px 11px}.right-panel{top:69px;right:10px;width:calc(50% - 15px);gap:6px}.section-heading,.map-head{font-size:7px}.status-chip{font-size:7px;padding:3px 5px}.vitals{gap:8px;padding:10px 0}.vital-row{gap:7px}.vital-icon{width:22px;height:22px;font-size:12px}.vital-label{font-size:7px;margin-bottom:4px}.log-copy{font-size:9px;line-height:1.4;margin:8px 0}.objective{font-size:8px;padding-top:8px;gap:5px}.objective-icon{font-size:13px}.panel-divider{margin-bottom:9px}.map-card,.inventory-card,.quick-actions{padding:8px}.map-coord{font-size:7px}.map-card #minimap{margin:6px 0 4px}.map-legend{font-size:7px;gap:9px}.inventory-grid{gap:3px;margin-top:7px}.inv-item{height:31px;font-size:14px}.action-button{height:36px;gap:5px}.action-button b{font-size:8px}.action-button small{font-size:7px;margin-top:2px}.action-icon{font-size:14px;width:15px}.shelter-tip{display:none}.bottom-ui{bottom:max(10px,env(safe-area-inset-bottom));gap:6px}.hotbar{height:61px;padding:4px}.hot-slot{width:47px;height:50px}.slot-label{font-size:6px}.slot-key{font-size:7px}.slot-symbol{font-size:17px}.controls-note{display:none}.interaction-hint{font-size:9px;min-height:24px}.toast{top:63px;font-size:9px}.start-card{padding:27px 26px 22px}.title-mark{margin:15px 0 5px}h1{font-size:48px}.intro{font-size:11px;margin:12px 0 18px}.start-details span{font-size:10px}.start-controls{font-size:7px}.overlay-side-note{bottom:10px;font-size:7px}}
@media(max-height:700px) and (min-width:621px){.left-panel{top:77px}.right-panel{top:77px;gap:7px}.map-card{padding:10px}.map-card #minimap{width:102px;height:102px;display:block;margin:7px auto}.bottom-ui{bottom:12px}.hotbar{height:65px}.vitals{padding:11px 0;gap:10px}.log-copy{margin:8px 0}}

(() => {
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap');
  const mctx = mini.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const WORLD = { w: 2400, h: 1800 };
  const rand = (seed) => { let n = seed >>> 0; return () => { n = (n * 1664525 + 1013904223) >>> 0; return n / 4294967296; }; };
  const random = rand(12931);
  let W = innerWidth, H = innerHeight, dpr = Math.min(devicePixelRatio || 1, 2);
  let started = false, ended = false, last = 0, gameSeconds = 8 * 60 + 20, dayLength = 145, elapsed = 0, toastTimer = 0;
  let muted = false, running = false, keys = {}, touchVector = {x:0,y:0};
  const player = { x: 1130, y: 920, r: 13, faceX: 1, faceY: 0, speed: 170 };
  const stats = { hunger: 78, thirst: 72, health: 100 };
  const bag = { berries: 2, water: 1, wood: 0, stone: 0 };
  let gathered = 0, days = 1, shelters = [], fires = [], particles = [];
  let objective = 'Find a source of fresh water';
  const resources = [];
  const add = (kind,x,y,extra={}) => resources.push({kind,x,y,active:true,phase:random()*6,...extra});
  // Deliberately clustered landmarks create readable routes around the forest clearing.
  for(let i=0;i<78;i++){
    const angle=random()*Math.PI*2, radius=130+random()*1000;
    const x=Math.max(55,Math.min(WORLD.w-55,player.x+Math.cos(angle)*radius));
    const y=Math.max(55,Math.min(WORLD.h-55,player.y+Math.sin(angle)*radius));
    if(Math.hypot(x-1460,y-660)<250 || Math.hypot(x-player.x,y-player.y)<120) continue;
    add('tree',x,y,{size:25+random()*17});
  }
  [[900,740],[1015,610],[1320,1000],[1510,980],[790,1110],[1190,520],[1570,800],[920,1280],[1700,1150],[690,830],[1390,1320],[1040,480]].forEach(([x,y])=>add('berry',x,y,{size:15}));
  [[1030,1040],[950,980],[1260,1160],[1360,1120],[820,960],[1600,920],[1220,470],[730,1150],[1760,750],[1480,1290],[1000,1230],[1170,1150],[780,660]].forEach(([x,y])=>add('rock',x,y,{size:11+random()*5}));
  [[1460,660],[1415,690],[1505,715],[1380,640],[1530,620],[1460,755]].forEach(([x,y])=>add('water',x,y,{size:20}));
  [[1045,925],[1070,920],[1085,946],[1052,950]].forEach(([x,y])=>add('scrap',x,y,{size:10}));
  const lake = {x:1450,y:660,rx:215,ry:145};
  function resize(){W=innerWidth;H=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
  addEventListener('resize',resize);
  const screen = (x,y) => ({x:x-camera.x+W/2,y:y-camera.y+H/2});
  const camera = {x:player.x,y:player.y};
  function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
  function ellipse(x,y,rx,ry,fill,stroke){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
  function rounded(x,y,w,h,r,fill){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();}
  function drawGround(){
    ctx.fillStyle='#426344';ctx.fillRect(0,0,W,H);
    const left=camera.x-W/2, top=camera.y-H/2;
    const startX=Math.floor(left/64)*64, startY=Math.floor(top/64)*64;
    for(let x=startX;x<left+W+64;x+=64) for(let y=startY;y<top+H+64;y+=64){
      const p=screen(x,y), shade=(Math.sin(x*.021+y*.008)+Math.cos(y*.017-x*.009))*1.6;
      ctx.fillStyle=shade>0?'rgba(181,190,115,.045)':'rgba(14,46,34,.055)';ctx.fillRect(p.x,p.y,65,65);
      let hash=Math.abs(Math.sin(x*12.98+y*78.23)*43758.5)%1;
      if(hash>.58){ctx.fillStyle=hash>.88?'rgba(216,207,146,.22)':'rgba(195,208,142,.15)';ctx.beginPath();ctx.ellipse(p.x+hash*55,p.y+(hash*93)%58,1.3,2.4,-.3,0,Math.PI*2);ctx.fill();}
    }
    // Worn trails through the clearing
    ctx.save();ctx.translate(W/2-camera.x,H/2-camera.y);ctx.strokeStyle='rgba(179,157,107,.13)';ctx.lineWidth=35;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(820,1040);ctx.bezierCurveTo(1000,900,1170,1030,1330,890);ctx.stroke();ctx.restore();
  }
  function drawLake(t){
    const p=screen(lake.x,lake.y);
    ctx.save();ctx.translate(p.x,p.y);ctx.rotate(-.16);
    ellipse(0,0,lake.rx+11,lake.ry+8,'rgba(27,65,53,.28)');
    ellipse(0,0,lake.rx,lake.ry,'#397c7a','#75a89a');
    ellipse(-7,-3,lake.rx-12,lake.ry-11,'#4d9991');
    ellipse(-20,-14,138,88,'rgba(133,190,164,.14)');
    for(let i=0;i<8;i++){const a=t*.3+i*1.7;ctx.strokeStyle=`rgba(190,221,184,${.1+((Math.sin(t+i)+1)*.025)})`;ctx.lineWidth=1.3;ctx.beginPath();ctx.ellipse(Math.sin(a)*95,Math.cos(a*1.3)*48,18+(i%3)*9,3,Math.sin(a),0,Math.PI*2);ctx.stroke();}
    ctx.restore();
    // Reeds along the bank
    for(let i=0;i<18;i++){let a=i*2.39;let x=lake.x+Math.cos(a)*(lake.rx+random()*14),y=lake.y+Math.sin(a)*(lake.ry+random()*11),s=screen(x,y);ctx.strokeStyle='#8c9c5e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x+Math.sin(t+i)*4,s.y-9);ctx.stroke();}
  }
  function drawTree(o,t){
    const p=screen(o.x,o.y);if(p.x<-70||p.x>W+70||p.y<-90||p.y>H+70)return;
    const s=o.size, sway=Math.sin(t*.6+o.phase)*1.5;
    ellipse(p.x+2,p.y+5,s*.66,s*.35,'rgba(12,31,22,.24)');
    ctx.fillStyle='#6b5034';ctx.fillRect(p.x-4,p.y-s*.55,8,s*.72);
    ellipse(p.x+sway,p.y-s*.72,s*.78,s*.73,'#254833');
    ellipse(p.x-s*.27+sway,p.y-s*.9,s*.52,s*.48,'#315a3d');
    ellipse(p.x+s*.29+sway,p.y-s*.89,s*.48,s*.52,'#3b6745');
    ellipse(p.x-s*.08+sway,p.y-s*1.12,s*.37,s*.31,'#4b714a');
    ellipse(p.x-s*.24,p.y-s*.83,s*.17,s*.13,'rgba(169,182,117,.13)');
    if(o.active){ctx.fillStyle='rgba(230,235,194,.42)';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('✦',p.x,p.y+4);}
  }
  function drawBerry(o,t){const p=screen(o.x,o.y);if(p.x<-35||p.x>W+35||p.y<-40||p.y>H+40)return;ellipse(p.x,p.y+5,13,7,'rgba(10,30,19,.25)');ellipse(p.x-3,p.y,11,8,'#648248');ellipse(p.x+4,p.y-2,10,7,'#789050');ctx.fillStyle='#bd5751';[[p.x-4,p.y-3],[p.x+3,p.y-5],[p.x+6,p.y+1]].forEach(([x,y])=>{ctx.beginPath();ctx.arc(x,y+Math.sin(t+o.phase)*.4,2.5,0,7);ctx.fill();});}
  function drawRock(o){const p=screen(o.x,o.y);if(p.x<-30||p.x>W+30||p.y<-30||p.y>H+30)return;ellipse(p.x,p.y+5,o.size*1.1,o.size*.58,'rgba(9,24,17,.23)');ctx.fillStyle='#838c78';ctx.beginPath();ctx.moveTo(p.x-o.size,p.y+3);ctx.lineTo(p.x-o.size*.55,p.y-o.size*.65);ctx.lineTo(p.x+o.size*.24,p.y-o.size*.83);ctx.lineTo(p.x+o.size,p.y-o.size*.14);ctx.lineTo(p.x+o.size*.65,p.y+o.size*.46);ctx.lineTo(p.x-o.size*.65,p.y+o.size*.49);ctx.closePath();ctx.fill();ctx.fillStyle='rgba(219,219,182,.3)';ctx.beginPath();ctx.moveTo(p.x-o.size*.55,p.y-o.size*.65);ctx.lineTo(p.x+o.size*.24,p.y-o.size*.83);ctx.lineTo(p.x+o.size*.05,p.y-o.size*.2);ctx.lineTo(p.x-o.size*.7,p.y-.5);ctx.fill();}
