function showToast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
function nearby(){
  let best=null,dist=Infinity;
  for(const o of resources){if(!o.active||o.kind==='water')continue;const d=Math.hypot(o.x-player.x,o.y-player.y);if(d<dist&&d<58){best=o;dist=d;}}
  const lakeDist=Math.hypot((player.x-lake.x)/lake.rx,(player.y-lake.y)/lake.ry);
  if(lakeDist<1.04&&lakeDist<dist/100){return {kind:'lake',distance:lakeDist};}
  return best?{...best,distance:dist}:null;
}
function interact(){
  if(!started||ended)return;
  const target=nearby();if(!target){showToast('Nothing to gather here. Explore the clearing.');return;}
  if(target.kind==='lake'){
    bag.water=Math.min(8,bag.water+3);gathered+=3;showToast('Fresh water collected · +3');objective='Gather food and build a shelter';$('logCopy').textContent='The lake is clear and cold. There are useful supplies scattered nearby.';
  }else if(target.kind==='tree'){
    const amount=2+Math.floor(random()*2);bag.wood+=amount;gathered+=amount;target.active=false;showToast(`Wood gathered · +${amount}`);objective=bag.wood>=8?'Build a shelter before night':'Gather 8 wood for a shelter';
  }else if(target.kind==='berry'){
    const amount=2+Math.floor(random()*2);bag.berries+=amount;gathered+=amount;target.active=false;showToast(`Wild berries gathered · +${amount}`);objective='Gather food and build a shelter';
  }else if(target.kind==='rock'){
    const amount=1+Math.floor(random()*2);bag.stone+=amount;gathered+=amount;target.active=false;showToast(`Stone gathered · +${amount}`);objective=bag.stone>=4?'Build a shelter before night':'Gather stone for a shelter';
  }else if(target.kind==='scrap'){
    bag.wood+=2;bag.stone+=1;gathered+=3;target.active=false;showToast('Useful supplies salvaged · +2 wood, +1 stone');objective='Find water and gather supplies';
  }
  updateUI();
}
function eat(){if(!started||ended)return;if(bag.berries<1){showToast('No berries in your pack. Find a berry bush.');return;}bag.berries--;stats.hunger=Math.min(100,stats.hunger+27);showToast('A handful of berries · hunger restored');updateUI();}
function drink(){if(!started||ended)return;if(bag.water<1){showToast('Your flask is empty. Find the lake and gather water.');return;}bag.water--;stats.thirst=Math.min(100,stats.thirst+34);showToast('Cool, fresh water · thirst restored');objective=bag.wood>=8&&bag.stone>=4?'Build a shelter before night':'Gather supplies for shelter';updateUI();}
function buildFire(){if(!started||ended)return;if(bag.wood<4||bag.stone<2){showToast('Need 4 wood and 2 stone to build a fire.');return;}bag.wood-=4;bag.stone-=2;fires.push({x:player.x+player.faceX*27,y:player.y+player.faceY*27});showToast('Campfire built · warmth for the night');updateUI();}
function buildShelter(){if(!started||ended)return;if(bag.wood<8||bag.stone<4){showToast('Need 8 wood and 4 stone to build a shelter.');return;}bag.wood-=8;bag.stone-=4;shelters.push({x:player.x,y:player.y});showToast('Shelter built · you can rest safely here');objective='Survive until the rescue plane returns';updateUI();}
function updateUI(){
  for(const [name,value] of Object.entries(stats)){$(name+'Num').textContent=Math.round(value)+'%';$(name+'Bar').style.width=clamp(value,0,100)+'%';}
  const status=stats.health<35?'CRITICAL':stats.thirst<30||stats.hunger<30?'WEAK':'STEADY';$('conditionText').textContent=status;$('conditionText').style.color=status==='STEADY'?'#bdd8a7':status==='WEAK'?'#e4be7e':'#e98e7e';
  $('berriesCount').textContent=bag.berries;$('waterCount').textContent=bag.water;
  const total=bag.berries+bag.water+bag.wood+bag.stone;$('packCount').textContent=`${total} / 24`;
  const items=[['◉',bag.berries,'#d88367'],['⌁',bag.water,'#84c6c2'],['⌁',bag.wood,'#c7a77b'],['◆',bag.stone,'#a9b49a']];
  $('inventory').innerHTML=items.map(([symbol,count,color])=>`<div class="inv-item ${count?'':'empty'}" style="color:${count?color:''}">${symbol}<em>${count}</em></div>`).join('');
  const clock=((Math.floor(gameSeconds/3600)%24)+'').padStart(2,'0')+':'+(Math.floor(gameSeconds/60)%60+'').padStart(2,'0');$('clock').textContent=clock;$('dayLabel').textContent='DAY '+String(days).padStart(2,'0');
  const hour=Math.floor(gameSeconds/3600)%24;const isNight=hour>=20||hour<6;$('weatherLabel').textContent=isNight?'NIGHTFALL · '+(hour<6?'COLD':'CLEAR'):'CLEAR SKIES';
  const target=nearby();$('hintText').textContent=target?(target.kind==='lake'?'Gather fresh water':target.kind==='tree'?'Gather wood':target.kind==='berry'?'Pick wild berries':target.kind==='rock'?'Gather stone':'Salvage supplies'):'Explore the forest';$('interactionHint').classList.toggle('visible',!!target&&started&&!ended);
  const coordN=Math.floor(player.y/20),coordE=Math.floor(player.x/20);$('coords').textContent=`N ${String(coordN).padStart(2,'0')}° · E ${String(coordE).padStart(2,'0')}°`;
  if(objective)$('objectiveText').textContent=objective;
}
